static inline void layer2_fwd(const float *restrict in, float *restrict out) {
    { /* output 0 */
      float32x4_t s0 = vdupq_n_f32(0.0f), s1 = vdupq_n_f32(0.0f);
      const float *W = WEIGHTS[2];
      for (int k = 0; k < 16; k += 8) {
        float32x4_t x0 = vld1q_f32(in + k);
        float32x4_t w0 = (float32x4_t){W[(k+0)*2+0], W[(k+1)*2+0], W[(k+2)*2+0], W[(k+3)*2+0]};
        s0 = vfmaq_f32(s0, x0, w0);
        if (k + 8 <= 16) {
          float32x4_t x1 = vld1q_f32(in + k + 4);
          float32x4_t w1 = (float32x4_t){W[(k+4)*2+0], W[(k+5)*2+0], W[(k+6)*2+0], W[(k+7)*2+0]};
          s1 = vfmaq_f32(s1, x1, w1);
        }
      }
      float acc = BIASES[2][0] + vaddvq_f32(vaddq_f32(s0, s1));
      out[0] = acc;
    }
    { /* output 1 */
      float32x4_t s0 = vdupq_n_f32(0.0f), s1 = vdupq_n_f32(0.0f);
      const float *W = WEIGHTS[2];
      for (int k = 0; k < 16; k += 8) {
        float32x4_t x0 = vld1q_f32(in + k);
        float32x4_t w0 = (float32x4_t){W[(k+0)*2+1], W[(k+1)*2+1], W[(k+2)*2+1], W[(k+3)*2+1]};
        s0 = vfmaq_f32(s0, x0, w0);
        if (k + 8 <= 16) {
          float32x4_t x1 = vld1q_f32(in + k + 4);
          float32x4_t w1 = (float32x4_t){W[(k+4)*2+1], W[(k+5)*2+1], W[(k+6)*2+1], W[(k+7)*2+1]};
          s1 = vfmaq_f32(s1, x1, w1);
        }
      }
      float acc = BIASES[2][1] + vaddvq_f32(vaddq_f32(s0, s1));
      out[1] = acc;
    }
}

